CREATE TABLE public.points_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,delta integer NOT NULL,reason text NOT NULL CHECK(reason IN ('vote','vote_interest','boost')),question_id uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.points_ledger TO authenticated;
GRANT ALL ON public.points_ledger TO service_role;
ALTER TABLE public.points_ledger ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users read own points" ON public.points_ledger FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE INDEX points_ledger_user_idx ON public.points_ledger(user_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.award_vote_points() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cat text; ints text[]; BEGIN IF NEW.anonymous THEN RETURN NEW; END IF; SELECT category INTO cat FROM public.questions WHERE id=NEW.question_id; SELECT interests INTO ints FROM public.profiles WHERE id=NEW.user_id; IF ints IS NULL THEN RETURN NEW; END IF; IF cat=ANY(ints) THEN INSERT INTO public.points_ledger(user_id,delta,reason,question_id) VALUES(NEW.user_id,2,'vote_interest',NEW.question_id); ELSE INSERT INTO public.points_ledger(user_id,delta,reason,question_id) VALUES(NEW.user_id,1,'vote',NEW.question_id); END IF; RETURN NEW; END; $$;
REVOKE EXECUTE ON FUNCTION public.award_vote_points() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER votes_award_points AFTER INSERT ON public.votes FOR EACH ROW EXECUTE FUNCTION public.award_vote_points();
CREATE OR REPLACE FUNCTION public.my_stats() RETURNS TABLE(points integer,streak integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH days AS(SELECT DISTINCT(created_at AT TIME ZONE 'UTC')::date AS d FROM public.votes WHERE user_id=auth.uid() AND anonymous=false),ranked AS(SELECT d,d-(row_number() OVER(ORDER BY d))::int AS grp FROM days),runs AS(SELECT max(d) AS last_day,count(*)::int AS len FROM ranked GROUP BY grp) SELECT COALESCE((SELECT sum(delta)::int FROM public.points_ledger WHERE user_id=auth.uid()),0),COALESCE((SELECT len FROM runs WHERE last_day>=(now() AT TIME ZONE 'UTC')::date-1 ORDER BY last_day DESC LIMIT 1),0) $$;
REVOKE EXECUTE ON FUNCTION public.my_stats() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.my_stats() TO authenticated;
ALTER TABLE public.questions ADD COLUMN boosted_until timestamptz;
CREATE OR REPLACE FUNCTION public.boost_question(p_question uuid) RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bal integer; q record; until_ts timestamptz; BEGIN SELECT * INTO q FROM public.questions WHERE id=p_question AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Question not found'; END IF; IF q.visibility<>'public' THEN RAISE EXCEPTION 'Only public questions can be boosted'; END IF; IF q.ends_at IS NOT NULL AND q.ends_at<=now() THEN RAISE EXCEPTION 'Voting has already ended'; END IF; IF q.boosted_until IS NOT NULL AND q.boosted_until>now() THEN RAISE EXCEPTION 'Already boosted'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); SELECT COALESCE(sum(delta),0) INTO bal FROM public.points_ledger WHERE user_id=auth.uid(); IF bal<10 THEN RAISE EXCEPTION 'You need 10 points to boost'; END IF; INSERT INTO public.points_ledger(user_id,delta,reason,question_id) VALUES(auth.uid(),-10,'boost',p_question); until_ts:=LEAST(now()+interval '24 hours',COALESCE(q.ends_at,now()+interval '24 hours')); UPDATE public.questions SET boosted_until=until_ts WHERE id=p_question; RETURN until_ts; END; $$;
REVOKE EXECUTE ON FUNCTION public.boost_question(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.boost_question(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.feed_page(p_voter uuid,p_interests text[],p_category text,p_sort text,p_limit int,p_offset int) RETURNS TABLE(id uuid,matched boolean) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT q.id,(p_interests IS NULL OR q.category=ANY(p_interests)) AS matched FROM public.questions q WHERE q.visibility='public' AND(q.ends_at IS NULL OR q.ends_at>now()) AND(p_category IS NULL OR q.category=p_category) AND(auth.uid() IS NULL OR q.user_id<>auth.uid()) AND(p_voter IS NULL OR NOT EXISTS(SELECT 1 FROM public.votes v WHERE v.question_id=q.id AND v.user_id=p_voter)) ORDER BY(p_interests IS NULL OR q.category=ANY(p_interests)) DESC,(q.boosted_until IS NOT NULL AND q.boosted_until>now()) DESC,CASE WHEN p_sort='ending' THEN q.ends_at END ASC NULLS LAST,q.created_at DESC,q.id LIMIT LEAST(GREATEST(p_limit,1),50) OFFSET GREATEST(p_offset,0) $$;